#!/usr/bin/env python3
"""闸门 3 产物：从 PhysicalAI-AV 的人工核验 OOD 标注构造驾驶域带标答评测集。

为什么是这份标注（而不是 obstacle / 公开 sample）：
  * `reasoning/ood_reasoning.parquet` 是**人工核验**的，卡片原话 "intended to support
    Vision-Language-Action (VLA) model evaluation"；
  * `labels/obstacle.offline` 卡片明确写 "autogenerated (non-GT) machine labels"
    —— 拿它当 ground truth 是把伪标签当标答，不能用；
  * 公开 sample (`dgural/...Sample`) 只有 mp4，samples.json 里零标注（已实测）。

任务设计（`event_cluster` 九分类 → 去掉 catch-all 后八分类多选）：
  * 原始 9 类严重不均衡（WORK_ZONES 占 49.2%）⇒ 直接用全量会让"永远答 work zone"
    拿到 49.2%，因此取**类别平衡子集**（每类 --per-class 个）；
  * **排除 `OTHER_LONGTAIL`**：它是无正面定义的兜底类，要求模型选它是 ill-posed；
  * 选项顺序按 item 随机（种子固定）⇒ 恒选某个字母只能拿到 1/8 = 12.5%。

取帧成本（为什么不整块下载）：1740 个 OOD clip 散落在 **1085 个 chunk**，每个 chunk zip
约 1.14 GB ⇒ 整块下载 ≈ 1.4 TB。HF 支持 range request，故用 HfFileSystem + zipfile
**只读中央目录再抽单个成员**：实测每 clip ≈ 10 s、磁盘瞬时 ~15 MB。

凭据：需要对 gated 数据集有权限的 HF token，从环境变量 `HF_TOKEN` 读取，**不写进仓库**。

用法：
    export HF_TOKEN=...        # 有 gated 权限的 token
    .venv/bin/python alpamayo-edge/data/harvest_ood_eval.py \
        --out alpamayo-edge/data/ood_eval --per-class 23
"""

import argparse
import json
import os
import random
import subprocess
import sys
import tempfile
import zipfile
from collections import defaultdict

REPO = "nvidia/PhysicalAI-Autonomous-Vehicles"
CAMERA = "camera_front_wide_120fov"
N_FRAMES = 6

# 兜底类：无正面定义，要求模型选它是 ill-posed ⇒ 不进评测集
EXCLUDE_CLUSTERS = {"OTHER_LONGTAIL"}

# event_cluster -> 人类可读选项文本（送给模型的就是右边这句）
CLUSTER_TEXT = {
    "WORK_ZONES_TEMP_TRAFFIC_CONTROL": "A work zone or temporary traffic control setup",
    "PEDESTRIAN_DENSITY_OR_CLOSE_PROXIMITY": "High pedestrian density, or pedestrians in close proximity to the vehicle",
    "SPECIAL_OR_UNCOMMON_VEHICLE_BEHAVIOR": "A special or uncommon vehicle behaviour",
    "CYCLISTS_AND_MICROMOBILITY_COMPLEX": "Cyclists or micromobility users in a complex interaction",
    "COMPLEX_INTERSECTION_INTERACTION": "A complex intersection interaction",
    "EMERGENCY_INCIDENT_SCENE": "An emergency or incident scene",
    "ROAD_DEBRIS_OR_SAFETY_TRACES": "Road debris or safety traces on the roadway",
    "ANIMALS_BIRDS_ROADKILL": "Animals, birds, or roadkill",
}

QUESTION = (
    "These frames come from the front-facing wide camera of a driving vehicle, in order. "
    "Which option best describes the most safety-relevant situation in this scene?"
)


def sh(cmd):
    """Run a command, raising with captured stderr on failure (exit code IS checked)."""
    r = subprocess.run(cmd, capture_output=True, text=True)
    if r.returncode != 0:
        raise RuntimeError(f"cmd failed ({r.returncode}): {' '.join(cmd[:4])}…\n{r.stderr[-400:]}")
    return r.stdout


def probe_duration(path):
    out = sh(["ffprobe", "-v", "error", "-select_streams", "v:0",
              "-show_entries", "stream=duration", "-of", "default=nw=1:nk=1", path])
    return float(out.strip().splitlines()[0])


def extract_frames(mp4, outdir):
    """均匀采 N_FRAMES 帧，原生分辨率不缩放（与闸门 2 的 av_frames/README.md 同口径）。

    闸门 2 里 fps 分母是写死的 20.166667；这里按实测 duration 计算，避免 clip 长度
    略有差异时采不到 6 帧。
    """
    os.makedirs(outdir, exist_ok=True)
    dur = probe_duration(mp4)
    sh(["ffmpeg", "-v", "error", "-i", mp4, "-vf", f"fps={N_FRAMES}/{dur}",
        "-frames:v", str(N_FRAMES), "-q:v", "2", os.path.join(outdir, "f%d.jpg"), "-y"])
    got = sorted(f for f in os.listdir(outdir) if f.endswith(".jpg"))
    if len(got) < N_FRAMES:
        raise RuntimeError(f"got {len(got)} frames, want {N_FRAMES}")
    return got


def assign_options(items, seed):
    """给每道题分配选项顺序，并让**每个字母恰好当正确答案 n/8 次**。

    早先的做法是"每题独立随机打乱选项"，结果 184 题的答案字母落在 15–30 之间
    ⇒ 恒选出现最多的那个字母能拿 16.3%，高于名义随机基线 12.5%。这里改成先构造
    "每字母 × n/8" 的目标字母表再整体打乱，把这个残余偏差彻底消掉。
    """
    clusters = sorted(CLUSTER_TEXT)
    letters = [chr(ord("A") + i) for i in range(len(clusters))]
    rng = random.Random(seed)

    q, rem = divmod(len(items), len(letters))
    targets = [L for L in letters for _ in range(q)]
    targets += rng.sample(letters, rem)          # 不能整除时余数随机摊给不同字母
    rng.shuffle(targets)

    order = list(items)
    rng.shuffle(order)                           # 别让字母与类别/chunk 顺序相关
    for it, want in zip(order, targets):
        others = [c for c in clusters if c != it["event_cluster"]]
        rng.shuffle(others)
        slots = [L for L in letters if L != want]
        mapping = {want: it["event_cluster"]}
        mapping.update(dict(zip(slots, others)))
        it["options"] = {L: CLUSTER_TEXT[mapping[L]] for L in letters}
        it["answer"] = want
    return items


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--out", default="alpamayo-edge/data/ood_eval")
    ap.add_argument("--per-class", type=int, default=23,
                    help="每类取多少（默认 23 = 最小类的全部）")
    ap.add_argument("--seed", type=int, default=20260731)
    ap.add_argument("--cache", default="/tmp/av_probe", help="标注 parquet 的本地缓存目录")
    ap.add_argument("--limit", type=int, default=0, help="只处理前 N 个（冒烟测试用）")
    args = ap.parse_args()

    tok = os.environ.get("HF_TOKEN")
    if not tok:
        sys.exit("HF_TOKEN not set — need a token with access to the gated dataset.")

    import pandas as pd
    from huggingface_hub import HfFileSystem, hf_hub_download

    def grab(fn):
        return hf_hub_download(REPO, fn, repo_type="dataset", local_dir=args.cache, token=tok)

    ood = pd.read_parquet(grab("reasoning/ood_reasoning.parquet"))
    idx = pd.read_parquet(grab("clip_index.parquet"))

    # ---- 类别平衡抽样 ----
    ood = ood[~ood["event_cluster"].isin(EXCLUDE_CLUSTERS)]
    rng = random.Random(args.seed)
    picked = []
    for cluster, grp in ood.groupby("event_cluster", sort=True):
        ids = sorted(grp.index)
        rng.shuffle(ids)
        take = ids[: args.per_class]
        if len(take) < args.per_class:
            print(f"[warn] {cluster}: only {len(take)} available (< {args.per_class})")
        picked += [(c, cluster) for c in take]
    rng.shuffle(picked)
    if args.limit:
        picked = picked[: args.limit]
    print(f"[plan] {len(picked)} clips over {len(set(c for _, c in picked))} classes")

    # ---- 按 chunk 分组：每个 zip 只打开一次（中央目录 ~4 s，别重复付） ----
    by_chunk = defaultdict(list)
    missing_idx = []
    for cid, cluster in picked:
        if cid not in idx.index:
            missing_idx.append(cid)
            continue
        by_chunk[int(idx.at[cid, "chunk"])].append((cid, cluster))
    if missing_idx:
        print(f"[warn] {len(missing_idx)} clips absent from clip_index, skipped")
    print(f"[plan] spans {len(by_chunk)} chunks")

    fs = HfFileSystem(token=tok)
    frames_root = os.path.join(args.out, "frames")
    os.makedirs(frames_root, exist_ok=True)
    manifest, failures = [], []

    def have_frames(cid):
        d = os.path.join(frames_root, cid)
        return os.path.isdir(d) and len([f for f in os.listdir(d) if f.endswith(".jpg")]) >= N_FRAMES

    for n, (chunk, items) in enumerate(sorted(by_chunk.items()), 1):
        zpath = (f"datasets/{REPO}/camera/{CAMERA}/{CAMERA}.chunk_{chunk:04d}.zip")
        # 该 chunk 的帧都已在本地 ⇒ 完全不碰网络（读中央目录要 ~4 s，175 个 chunk 就是 12 分钟）
        if all(have_frames(cid) for cid, _ in items):
            zf, names = None, None
        else:
            try:
                zf = zipfile.ZipFile(fs.open(zpath, "rb"))
                names = set(zf.namelist())
            except Exception as e:
                for cid, cl in items:
                    failures.append({"clip_id": cid, "stage": "open_zip", "err": f"{type(e).__name__}: {e}"[:200]})
                print(f"[{n}/{len(by_chunk)}] chunk {chunk}: OPEN FAILED {type(e).__name__}")
                continue

        for cid, cluster in items:
            outdir = os.path.join(frames_root, cid)
            member = f"{cid}.{CAMERA}.mp4"
            if have_frames(cid):
                got = sorted(f for f in os.listdir(outdir) if f.endswith(".jpg"))
            elif member not in names:
                failures.append({"clip_id": cid, "stage": "member", "err": "mp4 not in chunk"})
                continue
            else:
                tmp = None
                try:
                    with tempfile.NamedTemporaryFile(suffix=".mp4", delete=False) as t:
                        tmp = t.name
                        t.write(zf.read(member))
                    got = extract_frames(tmp, outdir)
                except Exception as e:
                    failures.append({"clip_id": cid, "stage": "extract", "err": f"{type(e).__name__}: {e}"[:200]})
                    continue
                finally:
                    if tmp and os.path.exists(tmp):
                        os.remove(tmp)          # 即下即删：mp4 不留

            # 选项与答案字母在循环结束后统一分配（见 assign_options）
            manifest.append({
                "clip_id": cid,
                "event_cluster": cluster,
                "split": str(ood.at[cid, "split"]),
                "question": QUESTION,
                "frames": [f"frames/{cid}/{f}" for f in got],
            })
        print(f"[{n}/{len(by_chunk)}] chunk {chunk}: ok={len(manifest)} fail={len(failures)}", flush=True)

    manifest = assign_options(manifest, args.seed)
    manifest.sort(key=lambda d: d["clip_id"])          # 稳定顺序，便于 diff

    os.makedirs(args.out, exist_ok=True)
    with open(os.path.join(args.out, "manifest.json"), "w") as f:
        json.dump({
            "source": f"{REPO} :: reasoning/ood_reasoning.parquet (human-verified)",
            "camera": CAMERA, "n_frames": N_FRAMES, "native_resolution": "1920x1080",
            "excluded_clusters": sorted(EXCLUDE_CLUSTERS),
            "per_class": args.per_class, "seed": args.seed,
            "n_items": len(manifest), "n_classes": len(CLUSTER_TEXT),
            "chance_baseline_pct": round(100.0 / len(CLUSTER_TEXT), 2),
            "items": manifest, "failures": failures,
        }, f, indent=1, ensure_ascii=False)
    print(f"\n[done] {len(manifest)} items, {len(failures)} failures -> {args.out}/manifest.json")
    if failures:
        from collections import Counter
        print("[failures by stage]", dict(Counter(f["stage"] for f in failures)))


if __name__ == "__main__":
    main()
